import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        int length = input.length();
        boolean replacedAt = false;
        StringBuilder output = new StringBuilder();

        for (int index = 0; index < length; ++index) {
            if (index == 0 && input.startsWith("at", index)) {
                output.append("at");
                index += 1;
            } else if (index == 0 && input.startsWith("dot", index)) {
                output.append("dot");
                index += 2;
            } else if (index == length - 2 && input.startsWith("at", index)) {
                output.append("at");
                break;
            } else if (index == length - 3 && input.startsWith("dot", index)) {
                output.append("dot");
                break;
            } else if (input.startsWith("at", index) && !replacedAt) {
                output.append("@");
                replacedAt = true;
                index += 1;
            } else if (input.startsWith("dot", index)) {
                output.append(".");
                index += 2;
            } else {
                output.append(input.charAt(index));
            }
        }
        System.out.println(output.toString());
    }
}
